def check_airport_code(S: str, T: str) -> str:
    if len(T) != 3 or not T.isupper():
        return "No"

    if T[-1] == 'X':
        T = T[0:2]
    T = T.lower()

    j = 0
    for i in range(len(T)):
        while j < len(S):
            if T[i] == S[j].lower():
                j += 1
                break
            j += 1
        else:
            return "No"

    return "Yes"
